const req = $input.first().json;
const requires_approval = req.cost_impact > 100.0 || req.category === 'LABOR_OVERTIME';
return [{ json: {
  approval_id: 'APR-' + Date.now(),
  requires_human_signoff: requires_approval,
  approver_role: 'OPERATIONS_SUPERVISOR',
  details: req
}}];

// Log workflow execution audit
const res = $input.all();
return res.map(r => ({ json: { ...r.json, _audit: { workflow: '10 - Human Approval Routing', processed_at: new Date().toISOString() } } }));
